type ChatcnMaskMode = "rect" | "brush"

/** A rectangle in fractions of the image: `{ x: 0.25, y: 0.1, width: 0.5, height: 0.4 }`. */
interface ChatcnMaskRect {
  x: number
  y: number
  width: number
  height: number
}

/** One brush stroke. Points and size are fractions of the image width and height. */
interface ChatcnMaskStroke {
  points: Array<[number, number]>
  /** Brush diameter as a fraction of the image width. */
  size: number
}

/** What the user marked for editing. `null` when nothing is marked. */
type ChatcnMaskSelection =
  | { kind: "rect"; rect: ChatcnMaskRect }
  | { kind: "brush"; strokes: ChatcnMaskStroke[] }
  | null

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export interface ImageEditRegionSubmit {
  prompt: string
  /** The marked region in fractions of the image. Build a PNG mask with `chatcnMaskToDataUrl`. */
  selection: Exclude<ChatcnMaskSelection, null>
}

export interface ImageEditRegionProps
  extends Omit<React.ComponentProps<"div">, "onSubmit" | "defaultValue"> {
  src: string
  /** Describe what the image shows. */
  alt: string
  /** Intrinsic size. Sets the frame's aspect ratio. */
  width?: number
  height?: number
  /** Width over height when `width` and `height` are unknown. */
  aspectRatio?: number
  mode?: ChatcnMaskMode
  defaultMode?: ChatcnMaskMode
  onModeChange?: (mode: ChatcnMaskMode) => void
  defaultSelection?: ChatcnMaskSelection
  onSelectionChange?: (selection: ChatcnMaskSelection) => void
  /** Brush diameter in px on screen. Default 32. */
  defaultBrushSize?: number
  /** Controlled description. */
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  placeholder?: string
  onSubmit?: (edit: ImageEditRegionSubmit) => void
  /** The edit is being applied: inputs lock and the button shows a spinner. */
  submitting?: boolean
  disabled?: boolean
  /** Label of the submit button. Default "Edit region". */
  submitLabel?: string
}

interface UseChatcnMediaMaskOptions {
  mode?: ChatcnMaskMode
  defaultMode?: ChatcnMaskMode
  onModeChange?: (mode: ChatcnMaskMode) => void
  /** A selection to start from, for example when reopening an edit. */
  defaultSelection?: ChatcnMaskSelection
  onSelectionChange?: (selection: ChatcnMaskSelection) => void
}

interface UseChatcnMediaMask {
  mode: ChatcnMaskMode
  setMode: (mode: ChatcnMaskMode) => void
  rect: ChatcnMaskRect | null
  strokes: ChatcnMaskStroke[]
  /** The stroke being drawn right now, not yet in history. */
  liveStroke: ChatcnMaskStroke | null
  selection: ChatcnMaskSelection
  /** Replace the rectangle. `commit: false` updates live while dragging without a history entry. */
  setRect: (rect: ChatcnMaskRect | null, options?: { commit?: boolean }) => void
  /** Save the live rectangle as one history entry, after a drag ends. */
  commitRect: () => void
  beginStroke: (point: [number, number], size: number) => void
  extendStroke: (point: [number, number]) => void
  endStroke: () => void
  undo: () => void
  redo: () => void
  clear: () => void
  canUndo: boolean
  canRedo: boolean
}

interface Snapshot {
  rect: ChatcnMaskRect | null
  strokes: ChatcnMaskStroke[]
}

function fromSelection(selection: ChatcnMaskSelection | undefined): Snapshot {
  if (selection?.kind === "rect") return { rect: selection.rect, strokes: [] }
  if (selection?.kind === "brush") return { rect: null, strokes: selection.strokes }
  return { rect: null, strokes: [] }
}

const clamp012 = (n: number) => Math.min(1, Math.max(0, n))

/** Keeps a rectangle inside the image with a minimum size of 2% on each side. */
function clampChatcnMaskRect(rect: ChatcnMaskRect): ChatcnMaskRect {
  const width = Math.min(1, Math.max(0.02, rect.width))
  const height = Math.min(1, Math.max(0.02, rect.height))
  return {
    x: Math.min(1 - width, clamp012(rect.x)),
    y: Math.min(1 - height, clamp012(rect.y)),
    width,
    height,
  }
}

/**
 * State for marking a region of an image: a rectangle or brush strokes, with undo and redo.
 * Everything is stored in fractions of the image, so it survives resizes and maps onto the
 * image's real pixels when you build the mask with `chatcnMaskToDataUrl`.
 *
 * The two tools keep separate marks: switching tools never throws away the other one, and the
 * active tool decides which mark `selection` reports.
 */
function useChatcnMediaMask({
  mode: modeProp,
  defaultMode = "rect",
  onModeChange,
  defaultSelection,
  onSelectionChange,
}: UseChatcnMediaMaskOptions = {}): UseChatcnMediaMask {
  const [modeState, setModeState] = React.useState<ChatcnMaskMode>(
    defaultSelection?.kind ?? defaultMode,
  )
  const mode = modeProp ?? modeState
  const [history, setHistory] = React.useState<{ stack: Snapshot[]; index: number }>(() => ({
    stack: [fromSelection(defaultSelection)],
    index: 0,
  }))
  const committed = history.stack[history.index] ?? { rect: null, strokes: [] }
  const [liveRect, setLiveRect] = React.useState<ChatcnMaskRect | null | undefined>(undefined)
  const [liveStroke, setLiveStroke] = React.useState<ChatcnMaskStroke | null>(null)

  const rect = liveRect === undefined ? committed.rect : liveRect
  const strokes = committed.strokes

  const push = React.useCallback((next: Snapshot) => {
    setHistory((h) => ({ stack: [...h.stack.slice(0, h.index + 1), next], index: h.index + 1 }))
  }, [])

  const selection: ChatcnMaskSelection = React.useMemo(() => {
    if (mode === "rect") return rect ? { kind: "rect", rect } : null
    return strokes.length > 0 ? { kind: "brush", strokes } : null
  }, [mode, rect, strokes])

  const onChange = React.useRef(onSelectionChange)
  onChange.current = onSelectionChange
  const first = React.useRef(true)
  React.useEffect(() => {
    if (first.current) {
      first.current = false
      return
    }
    onChange.current?.(selection)
  }, [selection])

  const setMode = React.useCallback(
    (next: ChatcnMaskMode) => {
      if (modeProp === undefined) setModeState(next)
      onModeChange?.(next)
    },
    [modeProp, onModeChange],
  )

  const setRect = React.useCallback(
    (next: ChatcnMaskRect | null, options?: { commit?: boolean }) => {
      const value = next ? clampChatcnMaskRect(next) : null
      if (options?.commit === false) {
        setLiveRect(value)
        return
      }
      setLiveRect(undefined)
      push({ rect: value, strokes: committed.strokes })
    },
    [committed.strokes, push],
  )

  const commitRect = React.useCallback(() => {
    if (liveRect === undefined) return
    setLiveRect(undefined)
    push({ rect: liveRect, strokes: committed.strokes })
  }, [liveRect, committed.strokes, push])

  const beginStroke = React.useCallback((point: [number, number], size: number) => {
    setLiveStroke({ points: [point], size })
  }, [])

  const extendStroke = React.useCallback((point: [number, number]) => {
    setLiveStroke((s) => {
      if (!s) return s
      const last = s.points[s.points.length - 1]
      // Skip points closer than 0.3% of the image: they add weight, not shape.
      if (last && Math.hypot(point[0] - last[0], point[1] - last[1]) < 0.003) return s
      return { ...s, points: [...s.points, point] }
    })
  }, [])

  const endStroke = React.useCallback(() => {
    // Read the stroke from render state, not inside an updater: updaters must stay pure.
    if (liveStroke) push({ rect: committed.rect, strokes: [...committed.strokes, liveStroke] })
    setLiveStroke(null)
  }, [liveStroke, committed, push])

  const undo = React.useCallback(() => {
    setLiveRect(undefined)
    setHistory((h) => ({ ...h, index: Math.max(0, h.index - 1) }))
  }, [])
  const redo = React.useCallback(() => {
    setLiveRect(undefined)
    setHistory((h) => ({ ...h, index: Math.min(h.stack.length - 1, h.index + 1) }))
  }, [])

  const clear = React.useCallback(() => {
    setLiveRect(undefined)
    if (mode === "rect") {
      if (committed.rect) push({ rect: null, strokes: committed.strokes })
    } else if (committed.strokes.length > 0) push({ rect: committed.rect, strokes: [] })
  }, [mode, committed, push])

  return {
    mode,
    setMode,
    rect,
    strokes,
    liveStroke,
    selection,
    setRect,
    commitRect,
    beginStroke,
    extendStroke,
    endStroke,
    undo,
    redo,
    clear,
    canUndo: history.index > 0,
    canRedo: history.index < history.stack.length - 1,
  }
}

type Corner = "nw" | "ne" | "sw" | "se"

type Drag =
  | { kind: "new"; origin: [number, number]; startPx: [number, number]; started: boolean }
  | { kind: "move"; origin: [number, number]; rect: ChatcnMaskRect }
  | { kind: "resize"; corner: Corner; rect: ChatcnMaskRect }
  | { kind: "brush" }

function useHatchId() {
  return `chatcn-hatch-${React.useId().replace(/[^a-zA-Z0-9]/g, "")}`
}

/* -------------------------------------------------------------------------------------------------
 * Helpers
 * -----------------------------------------------------------------------------------------------*/

const clamp01 = (n: number) => Math.min(1, Math.max(0, n))

const DRAG_THRESHOLD = 4

const pct = (n: number) => `${Math.round(n * 1000) / 10}%`

function describeRect(rect: ChatcnMaskRect) {
  return `Selection ${pct(rect.width)} wide and ${pct(rect.height)} tall, ${pct(rect.x)} from the left, ${pct(rect.y)} from the top`
}

const isMac = () =>
  typeof navigator !== "undefined" && /Mac|iPhone|iPad/.test(navigator.platform || "")

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

export type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
export type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
export function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

