/**
 * Monochrome hatching: a light line and a dark line side by side, so the mask reads on bright
 * and dark parts of any image alike.
 */
function HatchPattern({ id, spacing = 9 }: { id: string; spacing?: number }) {
  return (
    <pattern
      id={id}
      width={spacing}
      height={spacing}
      patternUnits="userSpaceOnUse"
      patternTransform="rotate(45)"
    >
      <line x1="0" y1="0" x2="0" y2={spacing} stroke="white" strokeWidth="2" strokeOpacity="0.8" />
      <line
        x1="2"
        y1="0"
        x2="2"
        y2={spacing}
        stroke="black"
        strokeWidth="1.25"
        strokeOpacity="0.45"
      />
    </pattern>
  )
}

/** Polyline points in the 1000-wide viewBox. A single tap becomes a dot. */
function strokePoints(points: Array<[number, number]>, H: number) {
  const list = points.map(([x, y]) => `${x * 1000},${y * H}`)
  if (list.length === 1) {
    const [x, y] = points[0] ?? [0, 0]
    list.push(`${x * 1000 + 0.1},${y * H}`)
  }
  return list.join(" ")
}

/** The kit's one spinner. 0.8 s per turn, slowed to 1.2 s under reduced motion. */
export function Spinner({ className, label }: { className?: string; label?: string }) {
  return (
    <svg
      viewBox="0 0 16 16"
      fill="none"
      role={label ? "img" : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      data-slot="spinner"
      className={cn("chatcn-spin size-3.5 shrink-0", className)}
