        d="M8 1.75A6.25 6.25 0 0 1 14.25 8"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
      />
    </svg>
  )
}

function Kbd({ className, ...props }: React.ComponentProps<"kbd">) {
  return (
    <kbd
      data-slot="kbd"
      className={cn(
        "rounded-(--chatcn-radius-xs) bg-(color:--chatcn-fill) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) inline-flex h-5 min-w-5 items-center justify-center px-1 font-sans tabular-nums shadow-[inset_0_-1px_0_var(--chatcn-alpha-300)]",
        className,
      )}
      {...props}
    />
  )
}

/* -------------------------------------------------------------------------------------------------
 * ImageEditRegion
 * -----------------------------------------------------------------------------------------------*/

/**
 * Mark part of an image and describe the change. Two tools: a rectangle (drag to draw, drag
 * inside to move, drag a corner to resize, or use the keyboard) and a brush for loose shapes.
 * The mask shows as monochrome hatching, with the rest of the image dimmed under a rectangle.
 */
export function ImageEditRegion({
  src,
  alt,
  width,
  height,
  aspectRatio,
  mode: modeProp,
  defaultMode,
  onModeChange,
  defaultSelection,
  onSelectionChange,
  defaultBrushSize = 32,
  value: valueProp,
  defaultValue = "",
  onValueChange,
  placeholder = "Describe the change, for example “replace with low fog”…",
  onSubmit,
  submitting = false,
  disabled = false,
  submitLabel = "Edit region",
  className,
  ...props
}: ImageEditRegionProps) {
  const mask = useChatcnMediaMask({
    mode: modeProp,
    defaultMode,
    onModeChange,
    defaultSelection,
    onSelectionChange,
  })
  const { mode, rect, strokes, liveStroke, selection } = mask
  const ratio = width && height ? width / height : (aspectRatio ?? 1)
  const locked = disabled || submitting

  const [valueState, setValueState] = React.useState(defaultValue)
  const value = valueProp ?? valueState
  const setValue = (next: string) => {
    if (valueProp === undefined) setValueState(next)
    onValueChange?.(next)
  }

  const [brush, setBrush] = React.useState(defaultBrushSize)
  const [cursor, setCursor] = React.useState<[number, number] | null>(null)
  const [announce, setAnnounce] = React.useState("")
  const stageRef = React.useRef<HTMLDivElement>(null)
  const drag = React.useRef<Drag | null>(null)
  const hatchId = useHatchId()
  const brushHatchId = useHatchId()
  const maskId = `${brushHatchId}-mask`
  const hintId = React.useId()
  const H = Math.round(1000 / ratio)

  const point = (event: React.PointerEvent): [number, number] => {
    const box = stageRef.current?.getBoundingClientRect()
    if (!box) return [0, 0]
    return [
      clamp01((event.clientX - box.left) / box.width),
      clamp01((event.clientY - box.top) / box.height),
    ]
  }

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>) => {
    if (locked || event.button !== 0) return
    const target = event.target as HTMLElement
    const p = point(event)
    event.currentTarget.setPointerCapture(event.pointerId)
    if (mode === "brush") {
      const box = stageRef.current?.getBoundingClientRect()
      mask.beginStroke(p, brush / (box?.width || 1))
      drag.current = { kind: "brush" }
      return
    }
    const corner = target.dataset.corner as Corner | undefined
    if (corner && rect) drag.current = { kind: "resize", corner, rect }
    else if (target.dataset.slot === "edit-region-rect" && rect)
      drag.current = { kind: "move", origin: p, rect }
    else
      drag.current = {
        kind: "new",
        origin: p,
        startPx: [event.clientX, event.clientY],
        started: false,
      }
  }

  const onPointerMove = (event: React.PointerEvent<HTMLDivElement>) => {
    const p = point(event)
    if (mode === "brush") setCursor(p)
    const d = drag.current
    if (!d) return
    if (d.kind === "brush") {
      mask.extendStroke(p)
    } else if (d.kind === "new") {
      // A few px of hysteresis, so a click does not replace the selection with a dot.
      if (
        !d.started &&
        Math.hypot(event.clientX - d.startPx[0], event.clientY - d.startPx[1]) < DRAG_THRESHOLD
      )
        return
      d.started = true
      mask.setRect(
        {
          x: Math.min(d.origin[0], p[0]),
          y: Math.min(d.origin[1], p[1]),
          width: Math.abs(p[0] - d.origin[0]),
          height: Math.abs(p[1] - d.origin[1]),
        },
        { commit: false },
      )
    } else if (d.kind === "move") {
      mask.setRect(
        { ...d.rect, x: d.rect.x + p[0] - d.origin[0], y: d.rect.y + p[1] - d.origin[1] },
        { commit: false },
      )
    } else if (d.kind === "resize") {
      const { x, y, width: w, height: h } = d.rect
      const left = d.corner.includes("w") ? p[0] : x
      const right = d.corner.includes("e") ? p[0] : x + w
      const top = d.corner.includes("n") ? p[1] : y
      const bottom = d.corner.includes("s") ? p[1] : y + h
      mask.setRect(
        {
          x: Math.min(left, right),
          y: Math.min(top, bottom),
          width: Math.abs(right - left),
          height: Math.abs(bottom - top),
        },
        { commit: false },
      )
    }
  }

  const onPointerUp = () => {
    const d = drag.current
    drag.current = null
    if (!d) return
    if (d.kind === "brush") mask.endStroke()
    else if (d.kind !== "new" || d.started) mask.commitRect()
  }

  const onStageKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (locked || mode !== "rect") return
    if (!rect) {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault()
        const next = { x: 0.25, y: 0.25, width: 0.5, height: 0.5 }
        mask.setRect(next)
        setAnnounce(describeRect(next))
      }
      return
    }
    if (event.key === "Delete" || event.key === "Backspace") {
      event.preventDefault()
      mask.setRect(null)
      setAnnounce("Selection cleared")
      return
    }
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
    const step = event.shiftKey ? 0.1 : 0.01
    const dx = { ArrowLeft: rtl ? step : -step, ArrowRight: rtl ? -step : step }[event.key] ?? 0
    const dy = { ArrowUp: -step, ArrowDown: step }[event.key] ?? 0
    if (!dx && !dy) return
    event.preventDefault()
    // Alt resizes from the end edges; plain arrows move. Live until the key comes up, so a held
    // key is one undo step.
    const next = event.altKey
      ? { ...rect, width: rect.width + dx, height: rect.height + dy }
      : { ...rect, x: rect.x + dx, y: rect.y + dy }
    mask.setRect(next, { commit: false })
    setAnnounce(describeRect(next))
  }

  const onRootKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (locked) return
    const target = event.target as HTMLElement
    // The description field keeps its own undo.
    if (target.tagName === "TEXTAREA") return
    const mod = event.metaKey || event.ctrlKey
    if (!mod) return
    const key = event.key.toLowerCase()
    if (key === "z" && !event.shiftKey) {
      event.preventDefault()
      mask.undo()
    } else if ((key === "z" && event.shiftKey) || key === "y") {
      event.preventDefault()
      mask.redo()
    }
  }

  const canSubmit = !locked && selection !== null && value.trim().length > 0
  const submit = () => {
    if (!canSubmit || !selection) return
    onSubmit?.({ prompt: value.trim(), selection })
  }

  const hint =
    mode === "rect"
      ? rect
        ? "Drag to move, drag a corner to resize."
        : "Drag on the image to mark the area to change."
      : strokes.length > 0 || liveStroke
        ? "Paint more, or undo the last stroke."
        : "Paint over the area to change."

  const mod = isMac() ? "⌘" : "Ctrl"
  const allStrokes = liveStroke ? [...strokes, liveStroke] : strokes

  return (
    // biome-ignore lint/a11y/noStaticElementInteractions: listens for undo and redo shortcuts from its controls
    <div
      data-slot="image-edit-region"
      data-mode={mode}
      data-submitting={submitting ? "" : undefined}
      onKeyDown={onRootKeyDown}
      className={cn("text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) flex w-full min-w-0 flex-col gap-3", className)}
      {...props}
    >
      {/* Toolbar. In a narrow frame the brush size takes its own row, full width, instead of
          squeezing the slider to nothing. */}
      <div className="@container min-w-0">
        <div
          data-slot="image-edit-region-toolbar"
          className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1 @min-[27rem]:flex-nowrap"
        >
          <ToggleGroup
            value={[mode]}
            onValueChange={(next) => {
              const picked = next[0] as ChatcnMaskMode | undefined
              if (picked) mask.setMode(picked)
            }}
            disabled={locked}
            aria-label="Selection tool"
            className="bg-(color:--chatcn-fill) rounded-(--chatcn-radius-md) flex h-8 shrink-0 items-center gap-0.5 p-0.5 pointer-coarse:h-11"
          >
            {(
              [
                { value: "rect", label: "Rectangle", icon: <SquareIcon /> },
                { value: "brush", label: "Brush", icon: <BrushIcon /> },
              ] as const
            ).map((tool) => (
              <Toggle
                key={tool.value}
                value={tool.value}
                className={cn(
                  "chatcn-focus rounded-(--chatcn-radius-sm) text-[0.8125rem]/[1.25rem] inline-flex h-full items-center gap-1.5 px-2.5 font-medium",
                  "text-(color:--chatcn-fg-subtle) ease-(--chatcn-ease-standard) transition-colors duration-150 [&_svg]:size-3.5",
                  "hover:text-(color:--chatcn-fg) data-[pressed]:bg-(color:--chatcn-card) data-[pressed]:text-(color:--chatcn-fg) data-[pressed]:shadow-(--chatcn-shadow-xs)",
                  "disabled:opacity-50",
                )}
              >
                {tool.icon}
                {tool.label}
              </Toggle>
            ))}
          </ToggleGroup>

          {mode === "brush" ? (
            <label className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) order-last flex min-w-0 basis-full items-center gap-2 ps-1 @min-[27rem]:order-none @min-[27rem]:basis-auto">
              <span className="shrink-0">Size</span>
              <input
                type="range"
                min={8}
                max={96}
                step={2}
                value={brush}
                disabled={locked}
                onChange={(event) => setBrush(Number(event.target.value))}
                aria-label="Brush size"
                aria-valuetext={`${brush} pixels`}
                className="accent-(color:--chatcn-fg) h-8 min-w-0 flex-1 cursor-pointer disabled:opacity-50 @min-[27rem]:w-24 @min-[27rem]:flex-none pointer-coarse:h-11"
              />
              <span className="w-10 shrink-0 tabular-nums">{brush}&nbsp;px</span>
            </label>
          ) : null}

          <div className="ms-auto flex shrink-0 items-center gap-0.5">
            <Tooltip content="Undo" shortcut={`${mod}Z`}>
              <Button
                size="icon-sm"
                aria-label="Undo"
                disabled={locked || !mask.canUndo}
                onClick={mask.undo}
                className="pointer-coarse:size-11"
              >
                <Undo2Icon className="rtl:-scale-x-100" />
              </Button>
            </Tooltip>
            <Tooltip content="Redo" shortcut={`⇧${mod}Z`}>
              <Button
                size="icon-sm"
                aria-label="Redo"
                disabled={locked || !mask.canRedo}
                onClick={mask.redo}
                className="pointer-coarse:size-11"
              >
                <Redo2Icon className="rtl:-scale-x-100" />
              </Button>
            </Tooltip>
            <Tooltip content="Clear selection">
              <Button
                size="icon-sm"
                aria-label="Clear selection"
                disabled={locked || selection === null}
                onClick={mask.clear}
                className="pointer-coarse:size-11"
              >
                <Trash2Icon />
              </Button>
            </Tooltip>
          </div>
        </div>
      </div>

      {/* Stage */}
      {/* biome-ignore lint/a11y/useSemanticElements: a focusable drawing surface, not a form fieldset */}
      <div
        ref={stageRef}
        role="group"
        aria-roledescription="Region selector"
        aria-label={`Mark a region of the image: ${alt}`}
        aria-describedby={hintId}
        tabIndex={locked ? -1 : 0}
        data-slot="image-edit-region-stage"
        onKeyDown={onStageKeyDown}
        onKeyUp={(event) => {
          if (event.key.startsWith("Arrow")) mask.commitRect()
        }}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onPointerLeave={() => setCursor(null)}
        className={cn(
          "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-fill) chatcn-focus relative isolate touch-none overflow-hidden select-none",
          locked ? "cursor-default" : mode === "brush" ? "cursor-none" : "cursor-crosshair",
        )}
        style={{ aspectRatio: ratio }}
      >
        <img
          src={src}
          alt={alt}
          width={width}
          height={height}
          draggable={false}
          className="pointer-events-none absolute inset-0 size-full object-cover"
        />

        {/* Brush mask: strokes cut a hatched layer out of nothing. */}
        {mode === "brush" && allStrokes.length > 0 ? (
          <svg
            aria-hidden="true"
            viewBox={`0 0 1000 ${H}`}
            preserveAspectRatio="none"
            className="pointer-events-none absolute inset-0 size-full"
          >
            <defs>
              <HatchPattern id={brushHatchId} spacing={14} />
              <mask id={maskId} maskUnits="userSpaceOnUse" x="0" y="0" width="1000" height={H}>
                {allStrokes.map((stroke, i) => (
                  <polyline
                    key={i}
                    points={strokePoints(stroke.points, H)}
                    fill="none"
                    stroke="white"
                    strokeWidth={stroke.size * 1000}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                ))}
              </mask>
            </defs>
            <g mask={`url(#${maskId})`}>
              <rect width="1000" height={H} fill="white" fillOpacity="0.18" />
              <rect width="1000" height={H} fill={`url(#${brushHatchId})`} />
            </g>
          </svg>
        ) : null}

        {/* Rectangle: hatched, with the rest of the image dimmed by a scrim around it. */}
        {mode === "rect" && rect ? (
          <div
            data-slot="edit-region-rect"
            className={cn(
              "absolute shadow-[0_0_0_9999px_var(--chatcn-scrim)]",
              locked ? "cursor-default" : "cursor-move",
            )}
            style={{
              left: pct(rect.x),
              top: pct(rect.y),
              width: pct(rect.width),
              height: pct(rect.height),
            }}
          >
            <svg aria-hidden="true" className="pointer-events-none absolute inset-0 size-full">
              <defs>
                <HatchPattern id={hatchId} />
              </defs>
              <rect width="100%" height="100%" fill={`url(#${hatchId})`} />
            </svg>
            {/* Double hairline: light outside, dark inside. */}
            <span className="pointer-events-none absolute inset-0 shadow-[0_0_0_1px_white,inset_0_0_0_1px_black]" />
            {locked
              ? null
              : (["nw", "ne", "sw", "se"] as const).map((corner) => (
                  <span
                    key={corner}
                    data-corner={corner}
                    aria-hidden="true"
                    className={cn(
                      "absolute size-2.5 rounded-[2px] bg-[white] shadow-[0_0_0_1px_black]",
                      // A 24 px hit area around the 10 px handle; 44 px on touch.
                      "before:absolute before:-inset-[7px] before:content-[''] pointer-coarse:before:-inset-[17px]",
                      corner.includes("n") ? "-top-[5px]" : "-bottom-[5px]",
                      corner.includes("w") ? "-left-[5px]" : "-right-[5px]",
                      corner === "nw" || corner === "se"
                        ? "cursor-nwse-resize"
                        : "cursor-nesw-resize",
                    )}
                  />
                ))}
          </div>
        ) : null}

        {/* Brush cursor: a ring the size of the brush. */}
        {mode === "brush" && cursor && !locked ? (
          <span
            aria-hidden="true"
            className="pointer-events-none absolute rounded-full shadow-[0_0_0_1px_white,inset_0_0_0_1px_black]"
            style={{
              width: brush,
              height: brush,
              left: `calc(${pct(cursor[0])} - ${brush / 2}px)`,
              top: `calc(${pct(cursor[1])} - ${brush / 2}px)`,
            }}
          />
        ) : null}

        {submitting ? (
          <span className="bg-(color:--chatcn-bg)/30 absolute inset-0 grid place-items-center">
            <span className="bg-(color:--chatcn-surface)/90 shadow-(--chatcn-shadow-md) rounded-(--chatcn-radius-md) text-[0.8125rem]/[1.25rem] flex items-center gap-2 px-3 py-1.5 font-medium backdrop-blur-md">
              <Spinner />
              Editing region
            </span>
          </span>
        ) : null}
        <span
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 rounded-[inherit] shadow-[inset_0_0_0_1px_var(--chatcn-alpha-400)]"
        />
      </div>

      <p
        id={hintId}
        className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) -mt-1 flex flex-wrap items-center gap-x-1.5 gap-y-1"
      >
        <span>{hint}</span>
        {mode === "rect" ? (
          <span className="max-sm:hidden">
            Keyboard: <Kbd>Enter</Kbd> to start, arrows to move, <Kbd>Alt</Kbd> + arrows to resize.
          </span>
        ) : null}
      </p>

      {/* Description */}
      <form
        data-slot="image-edit-region-form"
        onSubmit={(event) => {
          event.preventDefault()
          submit()
        }}
        className={cn(
          "bg-(color:--chatcn-card) shadow-(--chatcn-shadow-xs) rounded-(--chatcn-radius-lg) flex items-end gap-2 p-1.5 ps-3",
          "focus-within:shadow-(--chatcn-shadow-input-focus) ease-(--chatcn-ease-standard) transition-shadow duration-150",
        )}
      >
        <textarea
          rows={1}
          value={value}
          disabled={locked}
          onChange={(event) => setValue(event.target.value)}
          onKeyDown={(event) => {
            // Enter applies, Shift+Enter breaks the line, and never during IME composition.
            if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
              event.preventDefault()
              submit()
            }
          }}
          placeholder={placeholder}
          aria-label="Describe the edit"
          className={cn(
            "text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) placeholder:text-(color:--chatcn-fg-subtle) field-sizing-content max-h-40 min-h-8 min-w-0 flex-1 resize-none bg-transparent py-1.5 outline-none",
            "disabled:opacity-60",
          )}
        />
        <Button
          type="submit"
          variant="solid"
          size="md"
          disabled={!canSubmit}
          className="pointer-coarse:h-11"
        >
          {submitting ? <Spinner /> : null}
          {submitLabel}
        </Button>
      </form>

      <span aria-live="polite" className="sr-only">
        {announce}
      </span>
    </div>
  )
}

export default ImageEditRegion

