/**
 * Full-screen viewer for one image or a set. The canvas is solid, the image is contained, and
 * arrow keys page through a set (mirrored in right-to-left layouts). Paging swaps instantly:
 * it is keyboard-driven and frequent.
 */
function ImageLightbox({
  images,
  index,
  onIndexChange,
  open,
  onOpenChange,
  download = true,
}: ImageLightboxProps) {
  const count = images.length
  const current = images[Math.min(Math.max(index, 0), count - 1)]
  const many = count > 1
  const go = (delta: number) => onIndexChange?.((index + delta + count) % count)
  // Focus the stage, not the first button: a ring on Download right after opening is noise.
  const stageRef = React.useRef<HTMLDivElement>(null)

  if (!current) return null
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        size="full"
        initialFocus={stageRef}
        data-slot="image-lightbox"
        className="bg-(color:--chatcn-bg)"
        onKeyDown={(event) => {
          if (!many) return
          const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
          const next = rtl ? "ArrowLeft" : "ArrowRight"
          const prev = rtl ? "ArrowRight" : "ArrowLeft"
          if (event.key === next) {
            event.preventDefault()
            go(1)
          } else if (event.key === prev) {
            event.preventDefault()
            go(-1)
          }
        }}
      >
        <div className="flex h-13 shrink-0 items-center gap-3 ps-5 pe-14">
          <DialogTitle className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] min-w-0 flex-1 truncate font-medium">
            {current.caption ?? current.alt}
          </DialogTitle>
          {many ? (
            <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">
              {index + 1} of {count}
            </span>
          ) : null}
          {download ? (
            <Tooltip content="Download image">
              <a
                href={current.src}
                download={current.filename ?? filenameFrom(current.src)}
                aria-label="Download image"
                className={cn(
                  buttonVariants({ variant: "ghost", size: "icon-sm" }),
                  "pointer-coarse:size-11",
                )}
              >
                <DownloadIcon />
              </a>
            </Tooltip>
          ) : null}
        </div>

        <div
          ref={stageRef}
          tabIndex={-1}
          className="relative flex min-h-0 flex-1 items-center justify-center px-4 pb-4 outline-none sm:px-16"
        >
          <img
            key={current.src}
            src={current.src}
            alt={current.alt}
            width={current.width}
            height={current.height}
            draggable={false}
            className="rounded-(--chatcn-radius-md) max-h-full max-w-full object-contain select-none"
          />
          {many ? (
            <>
              <Button
                variant="outline"
                size="icon-md"
                aria-label="Previous image"
                onClick={() => go(-1)}
                className="absolute start-4 top-1/2 -translate-y-1/2 rounded-full max-sm:hidden pointer-coarse:size-11"
              >
                <ChevronLeftIcon className="rtl:-scale-x-100" />
              </Button>
              <Button
                variant="outline"
                size="icon-md"
                aria-label="Next image"
                onClick={() => go(1)}
                className="absolute end-4 top-1/2 -translate-y-1/2 rounded-full max-sm:hidden pointer-coarse:size-11"
              >
                <ChevronRightIcon className="rtl:-scale-x-100" />
              </Button>
            </>
          ) : null}
        </div>

        {many ? (
          <div className="flex shrink-0 justify-center gap-2 pb-4 sm:hidden">
            <Button
              variant="outline"
              size="icon-lg"
              aria-label="Previous image"
              onClick={() => go(-1)}
            >
              <ChevronLeftIcon className="rtl:-scale-x-100" />
            </Button>
            <Button variant="outline" size="icon-lg" aria-label="Next image" onClick={() => go(1)}>
              <ChevronRightIcon className="rtl:-scale-x-100" />
            </Button>
          </div>
        ) : null}
      </DialogContent>
    </Dialog>
  )
}

/**
 * A generated image in a conversation: the prompt and settings, one to four variations at their
 * final aspect ratio from the first paint, a progressive reveal while the model works, and actions
 * for the chosen variation once it is done.
 */
function ImageGeneration({
  prompt,
  status,
  images = [],
  count,
  aspectRatio = "1:1",
  progress,
  etaMs,
  queuePosition,
  statusText,
  settings,
  showPrompt = true,
  errorText,
  blockedText,
  onRetry,
  onCancel,
  onEditPrompt,
  onUpscale,
  onVary,
  onUseAsReference,
  onDownload,
  busyAction,
  selectedIndex: selectedProp,
  defaultSelectedIndex = 0,
  onSelectedIndexChange,
  className,
  ...props
}: ImageGenerationProps) {
  const total = clampCount(count ?? Math.max(images.length, 1))
  const ratio = parseAspectRatio(aspectRatio)
  const cols = columnsFor(total, ratio)
  const done = status === "done"

  // Restored from history: the first render is already done, so frames fade in without a reveal.
  const [instant] = React.useState(() => status === "done")

  const [selectedState, setSelectedState] = React.useState(defaultSelectedIndex)
  const selected = Math.min(selectedProp ?? selectedState, total - 1)
  const select = (index: number) => {
    if (selectedProp === undefined) setSelectedState(index)
    onSelectedIndexChange?.(index)
  }

  const [lightbox, setLightbox] = React.useState(false)
  const slots = Array.from({ length: total }, (_, i) => images[i])
  const ready = slots.flatMap((image, i) => (image?.src ? [{ image, i }] : []))
  const lightboxImages: ImageSource[] = ready.map(({ image, i }) => ({
    src: image.src as string,
    alt: image.alt ?? prompt,
    width: image.width,
    height: image.height,
    caption: prompt,
    filename: downloadName(image, prompt, i, total),
  }))
  const lightboxIndex = Math.max(
    0,
    ready.findIndex(({ i }) => i === selected),
  )
  const openLightbox = (index: number) => {
    if (!slots[index]?.src) return
    select(index)
    setLightbox(true)
  }

  const current = slots[selected]
  const tileRefs = React.useRef<Array<HTMLElement | null>>([])
  const selectable = done && total > 1

  const onGridKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (!selectable) return
    const rtl = getComputedStyle(event.currentTarget).direction === "rtl"
    const step: Record<string, number> = {
      ArrowRight: rtl ? -1 : 1,
      ArrowLeft: rtl ? 1 : -1,
      ArrowDown: cols,
      ArrowUp: -cols,
    }
    let next: number | undefined
    if (event.key in step) next = (selected + (step[event.key] ?? 0) + total) % total
    else if (event.key === "Home") next = 0
    else if (event.key === "End") next = total - 1
    else if (event.key === "Enter") {
      event.preventDefault()
      openLightbox(selected)
      return
    }
    if (next === undefined) return
    event.preventDefault()
    select(next)
    tileRefs.current[next]?.focus()
  }

  const percent = progress === undefined ? undefined : Math.round(Math.min(100, progress))
  const label = statusText ?? generationStage(progress, total > 1)
  const eta = useChatcnMediaEta(progress, { active: status === "generating", etaMs })
  const etaText = generationEtaLabel(eta, progress)
  const settled = status === "failed" || status === "blocked"
  const single = total === 1

  return (
    <div
      data-slot="image-generation"
      data-generation-state={status}
      aria-busy={status === "queued" || status === "generating" || undefined}
      className={cn("text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) flex w-full min-w-0 flex-col gap-3", className)}
      {...props}
    >
      {showPrompt ? (
        <div data-slot="image-generation-header" className="flex items-start gap-2">
          <div className="flex min-w-0 flex-1 flex-col gap-1">
            <p className="text-[0.875rem]/[1.25rem] tracking-[-0.003em] text-(color:--chatcn-fg) line-clamp-3 text-pretty">{prompt}</p>
            <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex flex-wrap items-center gap-x-1.5 tabular-nums">
              {[
                typeof aspectRatio === "string" ? aspectRatio : null,
                total > 1 ? `${total} variations` : null,
                ...(settings ?? []),
              ]
                .filter((item) => item !== null && item !== undefined && item !== false)
                .map((item, i) => (
                  <React.Fragment key={i}>
                    {i > 0 ? <span aria-hidden="true">·</span> : null}
                    <span>{item}</span>
                  </React.Fragment>
                ))}
            </p>
          </div>
          <CopyButton
            value={prompt}
            label="Copy prompt"
            size="icon-sm"
            className="-me-1 pointer-coarse:size-11"
          />
        </div>
      ) : null}

      <div className="relative">
        {/* biome-ignore lint/a11y/noStaticElementInteractions lint/a11y/useAriaPropsSupportedByRole: a radiogroup once the variations are done; inert before that */}
        <div
          role={selectable ? "radiogroup" : undefined}
          aria-label={selectable ? "Variations" : undefined}
          onKeyDown={onGridKeyDown}
          data-slot="image-generation-grid"
          data-count={total}
          className={cn("grid gap-1.5", single && ratio < 1 && "mx-auto")}
          style={{
            gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
            // A tall single image would fill the screen: cap its height at 32 rem.
            maxWidth: single && ratio < 1 ? `${Math.round(32 * ratio * 10) / 10}rem` : undefined,
          }}
        >
          {slots.map((image, i) => {
            const frameProgress = image?.progress ?? progress
            const alt = image?.alt ?? (total > 1 ? `${prompt} (variation ${i + 1})` : prompt)
            const frame = (
              <GenerationFrame
                image={image}
                phase={done && !image?.src ? "failed" : status}
                progress={frameProgress}
                ratio={ratio}
                instant={instant}
                alt={alt}
                className="size-full rounded-[inherit]"
              >
                {done && image?.src ? (
                  <span
                    aria-hidden="true"
                    className={cn(
                      "bg-(color:--chatcn-alpha-200) pointer-events-none absolute inset-0 opacity-0",
                      "ease-(--chatcn-ease-standard) transition-opacity duration-150",
                      "[@media(hover:hover)_and_(pointer:fine)]:group-hover/tile:opacity-100",
                    )}
                  />
                ) : null}
              </GenerationFrame>
            )
            const radius = single ? "rounded-(--chatcn-radius-lg)" : "rounded-(--chatcn-radius-md)"
            if (!done || !image?.src) {
              return (
                <div key={image?.id ?? image?.src ?? i} className={cn("relative", radius)}>
                  {frame}
                </div>
              )
            }
            if (single) {
              return (
                <button
                  key={image.id ?? image.src}
                  type="button"
                  aria-label={`Open image: ${alt}`}
                  onClick={() => openLightbox(i)}
                  className={cn(
                    "chatcn-focus group/tile relative block cursor-zoom-in text-start",
                    radius,
                  )}
                >
                  {frame}
                </button>
              )
            }
            const isSelected = i === selected
            return (
              // biome-ignore lint/a11y/useSemanticElements: a radio that shows an image, with roving focus
              <button
                key={image.id ?? image.src}
                ref={(node) => {
                  tileRefs.current[i] = node
                }}
                type="button"
                role="radio"
                aria-checked={isSelected}
                aria-label={`Variation ${i + 1}`}
                tabIndex={isSelected ? 0 : -1}
                onClick={() => select(i)}
                onDoubleClick={() => openLightbox(i)}
                data-selected={isSelected ? "" : undefined}
                className={cn("chatcn-focus group/tile relative block text-start", radius)}
              >
                {frame}
                <span
                  aria-hidden="true"
                  className={cn(
                    "pointer-events-none absolute inset-0 rounded-[inherit]",
                    "shadow-[inset_0_0_0_2px_var(--chatcn-accent),inset_0_0_0_3.5px_var(--chatcn-bg)]",
                    isSelected ? "opacity-100" : "opacity-0",
                  )}
                />
              </button>
            )
          })}
        </div>

        {status === "failed" ? (
          <GenerationNotice
            tone="error"
            icon={<CircleXIcon />}
            title="Image generation failed"
            actions={
              onRetry ? (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={onRetry}
                  className="pointer-coarse:h-11"
                >
                  <RotateCcwIcon />
                  Retry generation
                </Button>
              ) : null
            }
          >
            {errorText ?? "The image service stopped responding. Try again in a moment."}
          </GenerationNotice>
        ) : status === "blocked" ? (
          <GenerationNotice
            icon={<ShieldIcon />}
            title="This image wasn’t created"
            actions={
              onEditPrompt ? (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={onEditPrompt}
                  className="pointer-coarse:h-11"
                >
                  Edit prompt
                </Button>
              ) : null
            }
          >
            {blockedText ??
              "The prompt may go against the content policy. Try describing the scene and mood instead of a specific person or brand."}
          </GenerationNotice>
        ) : null}
      </div>

      {settled ? null : (
        <div data-slot="image-generation-footer" className="flex h-8 min-w-0 items-center gap-1">
          {status === "queued" ? (
            <div className="text-[0.8125rem]/[1.25rem] flex min-w-0 flex-1 items-center gap-2">
              <ClockIcon aria-hidden="true" className="text-(color:--chatcn-fg-subtle) size-3.5 shrink-0" />
              <span className="text-(color:--chatcn-fg-muted) shrink-0 font-medium">Queued</span>
              {queuePosition ? (
                <span className="text-(color:--chatcn-fg-subtle) shrink-0 whitespace-nowrap tabular-nums">
                  Position {queuePosition}
                </span>
              ) : null}
            </div>
          ) : status === "generating" ? (
            <div
              role="progressbar"
              aria-label={label}
              aria-valuemin={0}
              aria-valuemax={100}
              aria-valuenow={percent}
              aria-valuetext={
                [percent !== undefined ? `${percent}%` : null, etaText]
                  .filter(Boolean)
                  .join(", ") || undefined
              }
              className="text-[0.8125rem]/[1.25rem] flex min-w-0 flex-1 items-center gap-2"
            >
              <ShimmerText className="shrink-0">{label}</ShimmerText>
              {percent !== undefined ? (
                <span className="text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">{percent}%</span>
              ) : null}
              {etaText ? (
                <>
                  <span aria-hidden="true" className="text-(color:--chatcn-fg-subtle)">
                    ·
                  </span>
                  <span className="text-(color:--chatcn-fg-subtle) min-w-0 truncate tabular-nums">
                    {etaText}
                  </span>
                </>
              ) : null}
            </div>
          ) : (
            <div className="chatcn-scroll -ms-2.5 flex min-w-0 flex-1 items-center gap-0.5 overflow-x-auto">
              {onUpscale && current ? (
                <ActionButton
                  icon={<Maximize2Icon />}
                  busy={busyAction === "upscale"}
                  disabled={busyAction !== undefined}
                  onClick={() => onUpscale(current, selected)}
                >
                  Upscale
                </ActionButton>
              ) : null}
              {onVary && current ? (
                <ActionButton
                  icon={<ShuffleIcon />}
                  busy={busyAction === "vary"}
                  disabled={busyAction !== undefined}
                  onClick={() => onVary(current, selected)}
                >
                  Vary
                </ActionButton>
              ) : null}
              {onUseAsReference && current ? (
                <ActionButton
                  icon={<ImagePlusIcon />}
                  busy={busyAction === "reference"}
                  disabled={busyAction !== undefined}
                  onClick={() => onUseAsReference(current, selected)}
                >
                  Use as reference
                </ActionButton>
              ) : null}
            </div>
          )}

          {status === "queued" || status === "generating" ? (
            onCancel ? (
              <Button size="sm" onClick={onCancel} className="-me-2.5 pointer-coarse:h-11">
                Cancel
              </Button>
            ) : null
          ) : current?.src ? (
            <div className="-me-1.5 flex shrink-0 items-center gap-0.5">
              {total > 1 ? (
                <span className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) me-1.5 tabular-nums">
                  {selected + 1} of {total}
                </span>
              ) : null}
              <Tooltip content="Download">
                {onDownload ? (
                  <Button
                    size="icon-sm"
                    aria-label="Download image"
                    onClick={() => onDownload(current, selected)}
                    className="pointer-coarse:size-11"
                  >
                    <DownloadIcon />
                  </Button>
                ) : (
                  <a
                    href={current.src}
                    download={downloadName(current, prompt, selected, total)}
                    aria-label="Download image"
                    className={cn(
                      buttonVariants({ variant: "ghost", size: "icon-sm" }),
                      "pointer-coarse:size-11",
                    )}
                  >
                    <DownloadIcon />
                  </a>
                )}
              </Tooltip>
              <Tooltip content="Open">
                <Button
                  size="icon-sm"
                  aria-label="Open image"
                  onClick={() => openLightbox(selected)}
                  className="pointer-coarse:size-11"
                >
                  <MaximizeIcon />
                </Button>
              </Tooltip>
            </div>
          ) : null}
        </div>
      )}

      <span aria-live="polite" className="sr-only">
        {announcement(status, total, queuePosition)}
      </span>

      {lightboxImages.length > 0 ? (
        <ImageLightbox
          images={lightboxImages}
          index={lightboxIndex}
          onIndexChange={(index) => {
            const slot = ready[index]
            if (slot) select(slot.i)
          }}
          open={lightbox}
          onOpenChange={setLightbox}
        />
      ) : null}
    </div>
  )
}

const edited = scene("stairs", { seed: 9, ratio: 3 / 2 })

function ImageEditRegionDemo() {
  const [submitting, setSubmitting] = React.useState(false)
  const [prompt, setPrompt] = React.useState<string | null>(null)
  const job = useGenerationJob({ queue: [], durationMs: 3200, autoStart: false })

  return (
    <div className="flex w-full max-w-xl flex-col gap-10">
      <ImageEditRegion
        src={source.src}
        width={source.width}
        height={source.height}
        alt="Concrete stairs with a hand rail, a hard diagonal shadow across the wall"
        defaultSelection={{ kind: "rect", rect: { x: 0.08, y: 0.06, width: 0.42, height: 0.5 } }}
        defaultValue="Soften the shadow on the wall and let a little light spill through"
        submitting={submitting}
        onSubmit={(edit) => {
          setSubmitting(true)
          window.setTimeout(() => {
            setSubmitting(false)
            setPrompt(edit.prompt)
            job.run()
          }, 900)
        }}
      />
      {prompt ? (
        <ImageGeneration
          prompt={prompt}
          status={job.status}
          progress={job.progress}
          aspectRatio="3:2"
          images={[{ id: "edit", ...edited }]}
          settings={["Edit of region"]}
        />
      ) : null}
    </div>
  )
}

